// ============================================================
// CLASSIFICADOR AUTOMÁTICO DE E-MAILS
// Entrada: itens do gatilho do Gmail
// Saída:   item + { category, motivo, palavraChave, subject, from, ... }
// ============================================================

// --- 1. Palavras-chave do ASSUNTO que indicam URGÊNCIA ---
const PALAVRAS_URGENTE = [
  'urgent', 'urgente', 'urgencia', 'importante', 'important',
  'asap', 'critical', 'critico', 'emergencia', 'prioridade',
];

// --- 2. Palavras-chave do REMETENTE que indicam FINANCEIRO ---
const PALAVRAS_FINANCEIRO = [
  'bank', 'banco', 'nubank', 'itau', 'itaú', 'bradesco', 'santander',
  'caixa economica', 'invoice', 'boleto', 'payment slip', 'fatura',
  'pagamento', 'pix', 'cartao', 'cartão', 'financ',
];

// --- 3. Domínios / marcadores CORPORATIVOS (ajuste para a sua empresa) ---
const DOMINIOS_CORPORATIVOS = [
  '@company', '@work', '@empresa.com', '@empresa.com.br',
  '@corp.', '@grupocorp', '@company.com',
];

// --- 4. Palavras-chave do ASSUNTO que indicam PROMOÇÃO ---
const PALAVRAS_PROMOCAO = [
  'promotion', 'promocao', 'promoção', 'offer', 'oferta',
  'discount', 'desconto', 'coupon', 'cupom', 'sale', 'black friday',
];

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

/** Remove acentos, deixa minúsculo e apara espaços. */
const normalizar = (valor) =>
  String(valor === undefined || valor === null ? '' : valor)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();

/** Retorna a primeira palavra-chave encontrada no texto, ou null. */
const encontrar = (textoNormalizado, lista) =>
  lista.find((palavra) => textoNormalizado.includes(normalizar(palavra))) || null;

/** Extrai um cabeçalho do formato bruto do Gmail (payload.headers). */
const acharHeaderBruto = (lista, nome) => {
  const achado = lista.find((h) => normalizar(h && h.name) === nome);
  return achado && achado.value ? achado.value : '';
};

// ------------------------------------------------------------
// Classificação item a item
// ------------------------------------------------------------

return items.map((item) => {
  const json = item.json || {};
  const headers = json.headers || {};
  const headersBrutos = Array.isArray(json.payload?.headers) ? json.payload.headers : [];

  const assunto =
    json.subject || headers.subject || headers.Subject ||
    acharHeaderBruto(headersBrutos, 'subject') || '(sem assunto)';

  const remetente =
    json.from || headers.from || headers.From ||
    acharHeaderBruto(headersBrutos, 'from') || '(remetente desconhecido)';

  const destinatario =
    json.to || headers.to || headers.To ||
    acharHeaderBruto(headersBrutos, 'to') || '';

  const data =
    json.date || headers.date || headers.Date ||
    acharHeaderBruto(headersBrutos, 'date') || '';

  const resumo = json.snippet || json.textPlain || '';

  const assuntoNormalizado = normalizar(assunto);
  const remetenteNormalizado = normalizar(remetente);

  let category = 'Personal';
  let motivo = 'Nenhuma regra específica correspondeu (fallback: Personal).';
  let palavraChave = null;

  // Prioridade 1 - URGENTE (assunto)
  if ((palavraChave = encontrar(assuntoNormalizado, PALAVRAS_URGENTE))) {
    category = 'Urgent';
    motivo = `Assunto contém o termo de urgência "${palavraChave}".`;
  }
  // Prioridade 2 - FINANCEIRO (remetente)
  else if ((palavraChave = encontrar(remetenteNormalizado, PALAVRAS_FINANCEIRO))) {
    category = 'Financial';
    motivo = `Remetente contém o termo financeiro "${palavraChave}".`;
  }
  // Prioridade 3 - TRABALHO (remetente / domínio corporativo)
  else if ((palavraChave = encontrar(remetenteNormalizado, DOMINIOS_CORPORATIVOS))) {
    category = 'Work';
    motivo = `Remetente pertence a domínio corporativo ("${palavraChave}").`;
  }
  // Prioridade 4 - PROMOÇÕES (assunto)
  else if ((palavraChave = encontrar(assuntoNormalizado, PALAVRAS_PROMOCAO))) {
    category = 'Promotions';
    motivo = `Assunto contém o termo promocional "${palavraChave}".`;
  }

  return {
    json: {
      // --- campos originais preservados (usados pelos nós do Gmail) ---
      id: json.id,
      threadId: json.threadId,
      labelIds: json.labelIds || [],
      // --- resultado da classificação ---
      category,
      categoria: category,
      motivo,
      palavraChave,
      // --- dados úteis para notificações ---
      subject: assunto,
      from: remetente,
      to: destinatario,
      date: data,
      snippet: resumo,
      recebidoEm: new Date().toISOString(),
    },
  };
});

